1	<?php
2	/**
3	 * Interni poznamky k objednavce.
4	 * ?order=<uuid>
5	 */
6	
7	global $db;
8	legacy_db();
9	auth_require();
10	
11	$orderId = get_param('order');
12	if ($orderId == '') {
13	    $orderId = post_param('order');
14	}
15	
16	$objednavka = $db->one("SELECT id, status, customer_id FROM orders WHERE id = '" . $orderId . "'");
17	if ($objednavka === null) {
18	    echo '<p>Objednávka nenalezena</p>';
19	    return;
20	}
21	
22	if (is_post()) {
23	    csrf_check();
24	    $text = post_param('note');
25	    if ($text != '') {
26	        $db->exec("INSERT INTO order_notes (order_id, author, note, created_at) VALUES ('" . $orderId . "', '"
27	            . auth_login_name() . "', '" . db_escape_old($text) . "', '" . date('Y-m-d H:i:s') . "')");
28	        audit_log('order', $orderId, 'note');
29	    }
30	    $smazat = (int) post_param('delete', 0);
31	    if ($smazat > 0) {
32	        $db->exec("DELETE FROM order_notes WHERE id = " . $smazat);
33	    }
34	    redirect(admin_url('order_notes', array('order' => $orderId)));
35	    return;
36	}
37	
38	$poznamky = $db->query("SELECT * FROM order_notes WHERE order_id = '" . $orderId . "' ORDER BY created_at DESC");
39	
40	$pageTitle = 'Poznámky';
41	include LEGACY_TEMPLATES . '/partials/old_header.php';
42	?>
43	<h1>Poznámky k objednávce <?php echo h($orderId); ?></h1>
44	<p>Stav: <?php echo h(order_state_label($objednavka['status'])); ?>, zákazník: <?php echo h(customer_name($objednavka['customer_id'])); ?></p>
45	
46	<form method="post"><?php echo csrf_field(); ?>
47	    <input type="hidden" name="order" value="<?php echo h($orderId); ?>">
48	    <textarea name="note" rows="4" cols="70"></textarea><br>
49	    <input type="submit" value="Přidat poznámku">
50	</form>
51	
52	<?php foreach ($poznamky as $p) { ?>
53	<div style="border-bottom:1px solid #ddd;padding:5px 0">
54	    <strong><?php echo h($p['author']); ?></strong> – <?php echo format_date($p['created_at'], true); ?>
55	    <form method="post" style="display:inline" onsubmit="return confirm('Smazat poznámku?')"><?php echo csrf_field(); ?>
56	        <input type="hidden" name="order" value="<?php echo h($orderId); ?>">
57	        <input type="hidden" name="delete" value="<?php echo (int) $p['id']; ?>">
58	        <input type="submit" value="×">
59	    </form>
60	    <br><?php echo nl2br(h($p['note'])); ?>
61	</div>
62	<?php } ?>
63	<p><a href="<?php echo h(admin_url('order', array('id' => $orderId))); ?>">« objednávka</a></p>
64	<?php
65	include LEGACY_TEMPLATES . '/partials/old_footer.php';
