5	namespace App\Ordering\Infrastructure\EventHandler;
6	
7	use App\Ordering\Domain\Event\OrderCancelled;
8	use Doctrine\DBAL\Connection;
9	use Symfony\Component\Messenger\Attribute\AsMessageHandler;
10	
11	/**
12	 * Přidá automatickou poznámku k objednávce při storno.
13	 */
14	#[AsMessageHandler(bus: 'event.bus')]
15	final readonly class AddCancellationNoteHandler
16	{
17	    public function __construct(
18	        private Connection $db,
19	    ) {}
20	
21	    public function __invoke(OrderCancelled $event): void
22	    {
23	        $reason = $event->reason !== '' ? $event->reason : 'Objednávka zrušena';
24	        $note = 'Storno: ' . $reason . ' (' . $event->occurredAt->format('d.m.Y H:i') . ')';
25	
26	        $this->db->insert('order_notes', [
27	            'order_id' => $event->orderId->value,
28	            'author' => 'system',
29	            'note' => $note,
30	            'created_at' => $event->occurredAt->format('Y-m-d H:i:s'),
31	        ]);
32	    }
33	}
